export type LogoSize = "xs" | "sm" | "md" | "lg" | "xl";
export type LogoVariant = "default" | "white" | "dark";

export interface LogoProps {
  /** Size of the logo */
  size?: LogoSize;
  /** Color variant */
  variant?: LogoVariant;
  /** Show container box with background */
  withContainer?: boolean;
  /** Show text next to logo */
  withText?: boolean;
  /** Custom className */
  className?: string;
  /** Click handler */
  onClick?: () => void;
}

