    subtext: "text-xs",
    gap: "gap-2",
  },
  md: {
    container: "h-11 w-11 rounded-xl p-1.5",
    svg: "h-8 w-8",
    text: "text-lg",
    subtext: "text-xs",
    gap: "gap-2.5",
  },
  lg: {
    container: "h-14 w-14 rounded-2xl p-2",
    svg: "h-10 w-10",
    text: "text-xl",
    subtext: "text-sm",
    gap: "gap-3",
  },
  xl: {
    container: "h-20 w-20 rounded-3xl p-3",
    svg: "h-14 w-14",
    text: "text-2xl",
    subtext: "text-base",
    gap: "gap-4",
  },
} as const;

const containerVariants = {
  default: "bg-primary shadow-md",
  white: "bg-white shadow-md border border-border",
  dark: "bg-zinc-900 shadow-md",
} as const;

const textVariants = {
  default: "text-foreground",
  white: "text-zinc-900",
  dark: "text-white",
} as const;

